// Typed client generated from FastAPI's OpenAPI schema (schema.d.ts is generated by `npm run gen:api`; do not hand-edit).
import createClient from "openapi-fetch";
import type { paths, components } from "./schema";

export type Schemas = components["schemas"];
export type JobCard = Schemas["JobCard"];
export type JobDetail = Schemas["JobDetail"];
export type ApprovalOut = Schemas["ApprovalOut"];
export type RunOut = Schemas["RunOut"];
export type UserOut = Schemas["UserOut"];
export type HealthOut = Schemas["HealthOut"];
export type DecisionIn = Schemas["DecisionIn"];

const TOKEN_KEY = "gigbid_token";
export const getToken = () => {
  try { return localStorage.getItem(TOKEN_KEY); } catch { return null; }
};
export const setToken = (t: string | null) => {
  try { if (t) localStorage.setItem(TOKEN_KEY, t); else localStorage.removeItem(TOKEN_KEY); } catch { /* storage blocked */ }
};

const newTraceId = () => (crypto.randomUUID ? crypto.randomUUID().replace(/-/g, "") : String(Date.now()));

export const api = createClient<paths>({ baseUrl: "" });
api.use({
  onRequest({ request }) {
    const t = getToken();
    if (t) request.headers.set("Authorization", `Bearer ${t}`);
    request.headers.set("x-gigbid-trace-id", newTraceId()); // one trace id from the UI request onward
    return request;
  },
});

export function errorText(e: unknown): string {
  if (!e) return "";
  if (typeof e === "string") return e;
  const d = (e as { detail?: unknown }).detail;
  if (typeof d === "string") return d;
  if (Array.isArray(d)) return d.map((x) => (x as { msg?: string }).msg ?? "").join("; ");
  return "Something went wrong";
}
